import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Run your first search online","description":"","frontmatter":{},"headers":[],"relativePath":"get-started/online.md","filePath":"get-started/online.md","lastUpdated":1793111003000}'),o={name:"get-started/online.md"};function s(i,e,h,l,c,u){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="run-your-first-search-online" tabindex="-1">Run your first search online <a class="header-anchor" href="#run-your-first-search-online" aria-label="Permalink to &quot;Run your first search online&quot;">​</a></h1><p>Turn a question into a reading list on <a href="https://paperseek.app/" target="_blank" rel="noreferrer">paperseek.app</a> — no installation. About five minutes.</p><p>Prefer your own machine? <a href="./local">Install the Community edition</a>.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>An email address to create an account. During the public beta every account receives <strong>20 free credits a day</strong>; a search costs <strong>1 credit</strong>. See <a href="./../online/credits">Service &amp; credits</a>.</li><li>No account? You can run one temporary search without signing in — see <a href="./../online/privacy#search-without-signing-in">Search without signing in</a>. Temporary searches are not saved.</li></ul><h2 id="_1-sign-in" tabindex="-1">1. Sign in <a class="header-anchor" href="#_1-sign-in" aria-label="Permalink to &quot;1. Sign in&quot;">​</a></h2><p>Open <a href="https://paperseek.app/" target="_blank" rel="noreferrer">paperseek.app</a> and click <strong>Not signed in</strong> at the bottom of the sidebar, then choose <strong>Sign in or create an account</strong>. Enter your email address, confirm the verification code, and set a password. Details and other sign-in methods: <a href="./../online/account">Your account</a>.</p><h2 id="_2-ask-a-question" tabindex="-1">2. Ask a question <a class="header-anchor" href="#_2-ask-a-question" aria-label="Permalink to &quot;2. Ask a question&quot;">​</a></h2><p>After sign-in, <strong>PaperSeek Service</strong> is the active mode: models are provided by PaperSeek and tasks use your daily credits.</p><p>Open <strong>Search</strong> in the sidebar. Keep the default source <strong>OpenAlex</strong>, leave the budget on <strong>Auto</strong>, and type your question, for example:</p><blockquote><p>How does open-source software obtain funding for long-term maintenance?</p></blockquote><p>Select <strong>Start search</strong>, or press <strong>Ctrl+Enter / ⌘+Enter</strong>. The form shows the credits the task uses and how many remain today.</p><h2 id="_3-follow-the-search" tabindex="-1">3. Follow the search <a class="header-anchor" href="#_3-follow-the-search" aria-label="Permalink to &quot;3. Follow the search&quot;">​</a></h2><p>PaperSeek works in four visible stages: it interprets your question, iterates source-specific queries, retrieves and ranks candidates, then presents results. You can stop the run at any time from the header. What the stages and counts mean: <a href="./../guide/search">Search the literature</a>.</p><h2 id="_4-read-the-results" tabindex="-1">4. Read the results <a class="header-anchor" href="#_4-read-the-results" aria-label="Permalink to &quot;4. Read the results&quot;">​</a></h2><p>Open <strong>Results</strong> when the run finishes. Each paper shows its abstract, a relevance score with a written reason, and a link to the original record. Export the list as CSV, JSON, BibTeX, or RIS.</p><p>The run is saved to your account. Reopen it from <strong>Search history</strong> in the sidebar. From here you can also open a <a href="./../guide/citation-map">citation map</a>, run a <a href="./../guide/bibliometrics">bibliometric analysis</a>, or start an <a href="./../guide/reviews">experimental review</a>.</p><h2 id="what-next" tabindex="-1">What next? <a class="header-anchor" href="#what-next" aria-label="Permalink to &quot;What next?&quot;">​</a></h2><ul><li><a href="./../guide/search">Search the literature</a>: budgets, field filters, stopping and reconnecting.</li><li><a href="./../online/byok">Use your own keys</a>: your own model and data-source keys, no credits.</li><li><a href="./../online/credits">Service &amp; credits</a>: costs, refunds, and the daily refill.</li></ul>',19)])])}const f=a(o,[["render",s]]);export{p as __pageData,f as default};
